+import { join, resolve } from "@std/path";
+import { ConfigParseError } from "./errors.ts";
+import type { ConfigOptions, ConfigValues } from "./types.ts";
+
+export interface LoadedConfig {
+  path?: string;
+  values: ConfigValues;
+}
+
+function isPlainObject(value: unknown): value is Record<string, unknown> {
+  return typeof value === "object" && value !== null &&
+    !Array.isArray(value) && Object.getPrototypeOf(value) === Object.prototype;
+}
+
+function camelCase(key: string): string {
+  return key.replace(/-([a-zA-Z0-9])/g, (_, char) => char.toUpperCase());
+}
+
+function flatten(value: Record<string, unknown>, prefix = ""): ConfigValues {
+  const result: ConfigValues = {};
+  for (const [key, child] of Object.entries(value)) {
+    const name = prefix ? `${prefix}.${camelCase(key)}` : camelCase(key);
+    if (isPlainObject(child)) {
+      Object.assign(result, flatten(child, name));
+    } else {
+      result[name] = child;
+    }
+  }
+  return result;
+}
+
+function parseRc(content: string): ConfigValues {
+  const values: ConfigValues = {};
+  for (const line of content.split(/\\r?\
/)) {
+    const trimmed = line.trim();
+    if (!trimmed || trimmed.startsWith("#")) continue;
+    const index = trimmed.indexOf("=");
+    if (index < 1) throw new Error("Expected key=value pair.");
+    const key = camelCase(trimmed.slice(0, index).trim());
+    let value = trimmed.slice(index + 1).trim();
+    if (value.startsWith('"') && value.endsWith('"') && value.length >= 2) {
+      value = value.slice(1, -1);
+    } else if (value === "true" || value === "false") {
+      values[key] = value === "true";
+      continue;
+    } else if (/^-?(?:\\d+\\.?\\d*|\\.\\d+)$/.test(value)) {
+      values[key] = Number(value);
+      continue;
+    }
+    values[key] = value;
+  }
+  return values;
+}
+
+function configPath(directory: string, name: string, format: string): string {
+  return join(directory, format === ".rc" ? `.${name}rc` : `${name}${format}`);
+}
+
+export async function loadConfig(options: ConfigOptions): Promise<LoadedConfig> {
+  const formats = options.formats ?? [".json", ".rc"];
+  const paths = options.searchPaths ?? [Deno.cwd()];
+  const matches: string[] = [];
+  for (const directory of paths) {
+    for (const format of formats) {
+      const path = resolve(configPath(directory, options.name, format));
+      try {
+        const stat = await Deno.stat(path);
+        if (stat.isFile) matches.push(path);
+      } catch (error) {
+        if (!(error instanceof Deno.errors.NotFound)) throw error;
+      }
+      if (matches.length && !options.mergeConfigs) break;
+    }
+    if (matches.length && !options.mergeConfigs) break;
+  }
+
+  if (!matches.length) return { values: {} };
+  const values: ConfigValues = {};
+  // Earlier search paths take precedence, so only fill values not seen yet.
+  for (const path of matches) {
+    try {
+      const content = await Deno.readTextFile(path);
+      const parsed = options.parser
+        ? options.parser(content)
+        : path.endsWith(".rc") ? parseRc(content) : JSON.parse(content);
+      if (!isPlainObject(parsed)) throw new Error("Expected a plain object.");
+      const flattened = flatten(parsed);
+      for (const [key, value] of Object.entries(flattened)) {
+        if (!(key in values)) values[key] = value;
+      }
+    } catch (error) {
+      if (error instanceof ConfigParseError) throw error;
+      throw new ConfigParseError(path, error);
+    }
+  }
+  return { path: matches[0], values };
+}
