+import { assertEquals, assertRejects } from "@std/assert";
+import { test } from "@cliffy/internal/testing/test";
+import { setEnv, deleteEnv } from "@cliffy/internal/runtime/set-env";
+import { Command } from "../../command.ts";
+import { ConfigParseError, ConfigValidationError } from "../../config/mod.ts";
+
+async function withConfig(
+  files: Record<string, string>,
+  callback: (directory: string) => Promise<void>,
+) {
+  const directory = await Deno.makeTempDir();
+  try {
+    await Promise.all(
+      Object.entries(files).map(([name, content]) =>
+        Deno.writeTextFile(`${directory}/${name}`, content)
+      ),
+    );
+    await callback(directory);
+  } finally {
+    await Deno.remove(directory, { recursive: true });
+  }
+}
+
+test("[command] - config - loads JSON defaults and flattens values", async () => {
+  await withConfig({
+    "app.json": JSON.stringify({
+      "log-level": "debug",
+      enabled: false,
+      retries: 0,
+      tags: ["one", "two"],
+      nested: { "cache-size": 10 },
+    }),
+  }, async (directory) => {
+    const command = new Command()
+      .throwErrors()
+      .option("--log-level <value>", "...")
+      .option("--enabled", "...")
+      .option("--retries <value:number>", "...")
+      .option("--tags <value>", "...", { collect: true })
+      .config({ name: "app", searchPaths: [directory] });
+    const result = await command.parse([]);
+
+    assertEquals(result.options, {
+      logLevel: "debug",
+      enabled: false,
+      retries: 0,
+      tags: ["one", "two"],
+    });
+    assertEquals(command.getConfigPath(), `${directory}/app.json`);
+    assertEquals(command.getConfigValues(), {
+      logLevel: "debug",
+      enabled: false,
+      retries: 0,
+      tags: ["one", "two"],
+      "nested.cacheSize": 10,
+    });
+  });
+});
+
+test("[command] - config - supports RC files and precedence", async () => {
+  await withConfig({
+    ".apprc": '# comment\
name="config value"\
enabled=false\
retries=0\
',
+  }, async (directory) => {
+    setEnv("APP_NAME", "environment");
